<template><div v-loading="busy" class="panel"><h2>区域奖励与待激活记录</h2><el-button @click="load">刷新奖励</el-button><el-table :data="orders"><el-table-column prop="reportId" label="线索" /><el-table-column prop="userId" label="用户" /><el-table-column prop="amount" label="金额" /><el-table-column prop="state" label="账务状态" /><el-table-column label="处理"><template slot-scope="s"><el-button v-if="['RESERVED','CREDITED'].includes(s.row.state)" type="text" @click="correct(s.row)">发起或重试更正</el-button></template></el-table-column></el-table><div class="pagination"><el-button :disabled="page===1" @click="page--;load()">上一页</el-button><el-button :disabled="orders.length<20" @click="page++;load()">下一页</el-button></div><h2>历史批准意图</h2><p class="muted small">历史批准需要管理员核对后显式激活；余额不足的更正会进入人工追偿，不会虚构退款。</p><el-table :data="intents"><el-table-column prop="report_id" label="线索" /><el-table-column prop="user_id" label="用户" /><el-table-column prop="amount" label="金额" /><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="activate(s.row)">核对并激活</el-button></template></el-table-column></el-table></div></template>
<script>
import { api, message } from './client'
export default { data() { return { busy: false, page: 1, orders: [], intents: [] } }, created() { this.load() }, methods: { async fetch() { this.orders = (await api.get('/management/rewards', { page: this.page })).items; this.intents = (await api.get('/management/approval-intents', { page: this.page })).items }, async work(action) { if (this.busy) return; this.busy = true; try { await action() } catch (e) { if (e !== 'cancel' && e !== 'close') this.$message.error(message(e)) } finally { this.busy = false } }, load() { this.work(() => this.fetch()) }, correct(row) { this.work(async () => { const input = await this.$prompt('核对线索并填写原因；重试更正须使用原原因', '奖励更正'); const result = await api.post(`/rewards/${row.id}/corrections`, { reason: input.value }); this.$alert(result.state === 'MANUAL_REQUIRED' ? '余额不足，已记录人工追偿。请先核对提现冻结或历史结算。' : '更正已完成，原流水保留。', '处理结果'); await this.fetch() }) }, activate(row) { this.work(async () => { const input = await this.$prompt('确认历史审核依据和预算，填写激活原因', '历史奖励激活'); await api.post(`/approval-intents/${row.id}/activate`, { reason: input.value }); await this.fetch() }) } } }
</script>
